		if m.cursor[0] < 8 {
			m.cursor[0]++
		}
	case "left", "h":
		if m.cursor[1] > 0 {
			m.cursor[1]--
		}
	case "right", "l":
		if m.cursor[1] < 8 {
			m.cursor[1]++
		}
	case "n":
		if m.inputMode == ModDigit {
			m.inputMode = ModNote
		} else {
			m.inputMode = ModDigit
