func (m *Model) handleKey(msg tea.KeyMsg) tea.Cmd {
	key := msg.String()

	switch key {
	case "esc":
		return func() tea.Msg {
			return msgs.GameOverMsg{
				Won:     false,
				Elapsed: m.timer.elapsedSeconds(),
				Diff:    m.difficulty,
