		idx-- // shift to base indices
	}
	switch idx {
	case 0: // New Game
		m.showDiff = true
		return nil
	case 1: // Puzzle Library
		return func() tea.Msg { return msgs.NavigateMsg{To: msgs.ScreenLibrary} }
	case 2: // History
		return func() tea.Msg { return msgs.NavigateMsg{To: msgs.ScreenHistory} }
