package historyscreen

import (
	"fmt"
	"strings"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"

	"github.com/davidojeda/sudoku-tui/internal/msgs"
	"github.com/davidojeda/sudoku-tui/internal/history"
	"github.com/davidojeda/sudoku-tui/internal/theme"
)

const pageSize = 8

// Model is the history screen.
type Model struct {
	store   *history.Store
	entries []history.Entry
	cursor  int
	page    int
	width   int
	height  int
	theme   *theme.Theme
}

// New creates a new history screen model.
func New(th *theme.Theme, store *history.Store) *Model {
	entries := []history.Entry{}
	if store != nil {
		entries = store.All()
	}
	return &Model{
		store:   store,
		entries: entries,
		theme:   th,
	}
}

// SetTheme updates the theme on the history screen.
func (m *Model) SetTheme(th *theme.Theme) { m.theme = th }

func (m *Model) Init() tea.Cmd { return nil }

func (m *Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
	case tea.KeyMsg:
		switch msg.String() {
		case "esc", "q":
			return m, func() tea.Msg { return msgs.NavigateMsg{To: msgs.ScreenMenu} }
		case "up", "w":
			if m.cursor > 0 {
				m.cursor--
				if m.cursor < m.page*pageSize {
					m.page--
				}
			}
		case "down", "s":
			if m.cursor < len(m.entries)-1 {
				m.cursor++
				if m.cursor >= (m.page+1)*pageSize {
					m.page++
				}
			}
		case "pgdown":
			m.page++
			maxPage := (len(m.entries) - 1) / pageSize
			if maxPage < 0 {
				maxPage = 0
			}
			if m.page > maxPage {
				m.page = maxPage
			}
			m.cursor = m.page * pageSize
		case "pgup":
			if m.page > 0 {
				m.page--
			}
			m.cursor = m.page * pageSize
		}
	}
	return m, nil
}

func (m *Model) View() string {
	th := m.theme
	header := th.Header.Bar.Width(m.width).Render(" " + th.Header.Title.Render("HISTORY"))

	var stats history.Stats
	if m.store != nil {
		stats = m.store.Stats()
	} else {
		stats = history.Stats{BestTimes: map[string]int64{}}
	}
	statsRow := m.renderStats(stats)

	table := m.renderTable()

	total := len(m.entries)
	pages := (total + pageSize - 1) / pageSize
	if pages == 0 {
		pages = 1
	}
	start := m.page*pageSize + 1
	end := minInt(m.page*pageSize+pageSize, total)
	if total == 0 {
		start = 0
		end = 0
	}
	pagination := th.History.Pagination.Render(
		fmt.Sprintf("  SHOWING %d-%d OF %d   PAGE %d/%d", start, end, total, m.page+1, pages))

	hints := th.Footer.KeyHint.Render("w/s") + th.Footer.KeyLabel.Render(" Scroll") +
		"   " + th.Footer.KeyHint.Render("PgDn/PgUp") + th.Footer.KeyLabel.Render(" Page") +
		"   " + th.Footer.KeyHint.Render("Esc") + th.Footer.KeyLabel.Render(" Back")
	footer := th.Footer.Bar.Width(m.width).Render("  " + hints)

	body := lipgloss.JoinVertical(lipgloss.Left,
		"",
		statsRow,
		"",
		table,
		"",
		pagination,
	)

	bodyHeight := m.height - lipgloss.Height(header) - lipgloss.Height(footer)
	body = lipgloss.NewStyle().Height(bodyHeight).Render(body)

	return lipgloss.JoinVertical(lipgloss.Left, header, body, footer)
}

func (m *Model) renderStats(stats history.Stats) string {
	th := m.theme
	boxes := []string{
		th.History.StatBox.Render(
			th.History.StatLabel.Render("TOTAL GAMES") + "\n" +
				th.History.StatValue.Render(fmt.Sprintf("   %d   ", stats.Total))),
		th.History.StatBox.Render(
			th.History.StatLabel.Render(" WIN RATE ") + "\n" +
				th.History.StatValue.Render(fmt.Sprintf("  %d%%  ", stats.WinRate))),
		th.History.StatBox.Render(
			th.History.StatLabel.Render(" BEST (HARD)") + "\n" +
				th.History.StatValue.Render("  "+stats.BestTimeFormatted("Hard")+"  ")),
		th.History.StatBox.Render(
			th.History.StatLabel.Render("  STREAK  ") + "\n" +
				th.History.StatValue.Render(fmt.Sprintf("    %d    ", stats.Streak))),
	}
	return "  " + lipgloss.JoinHorizontal(lipgloss.Top, boxes[0], "  ", boxes[1], "  ", boxes[2], "  ", boxes[3])
}

func (m *Model) renderTable() string {
	th := m.theme
	header := th.History.TableHeader.Render(
		fmt.Sprintf("  %-20s %-12s %-10s %-10s", "DATE", "DIFFICULTY", "TIME", "RESULT"))
	sep := th.History.TableHeader.Render("  " + strings.Repeat("-", 56))

	var lines []string
	lines = append(lines, header, sep)

	start := m.page * pageSize
	end := start + pageSize
	if end > len(m.entries) {
		end = len(m.entries)
	}

	for i := start; i < end; i++ {
		e := m.entries[i]
		dateStr := e.Date
		if len(dateStr) > 16 {
			dateStr = dateStr[:16]
		}
		var resultStyle lipgloss.Style
		resultStr := string(e.Result)
		if e.Result == history.ResultWin {
			resultStyle = th.History.BadgeWin
		} else {
			resultStyle = th.History.BadgeLoss
		}

		line := fmt.Sprintf("  %-20s %-12s %-10s", dateStr, e.Difficulty, e.FormattedTime())
		if i == m.cursor {
			line = th.History.RowActive.Render(">" + line[1:]) + resultStyle.Render(resultStr)
		} else {
			line = th.History.Row.Render(line) + resultStyle.Render(resultStr)
		}
		lines = append(lines, line)
	}

	if len(m.entries) == 0 {
		lines = append(lines, th.History.Row.Render("  No games played yet."))
	}

	return strings.Join(lines, "\n")
}

func minInt(a, b int) int {
	if a < b {
		return a
	}
	return b
}

package menu

import (
	"strings"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"

	"github.com/davidojeda/sudoku-tui/internal/msgs"
	"github.com/davidojeda/sudoku-tui/internal/generator"
	"github.com/davidojeda/sudoku-tui/internal/theme"
)

// diffItem represents a difficulty option.
type diffItem struct {
	label string
	clues string
	desc  string
	diff  generator.Difficulty
}

var diffItems = []diffItem{
	{"EASY", "36-40 clues", "Solvable with naked and hidden singles only. A warm-up.", generator.Easy},
	{"MEDIUM", "30-35 clues", "Requires naked pairs and pointing pairs. Good daily practice.", generator.Medium},
	{"HARD", "25-29 clues", "Advanced patterns required. Focused solving needed.", generator.Hard},
	{"EXPERT", "17-24 clues", "X-Wing, Y-Wing, and Swordfish. Not for the faint-hearted.", generator.Expert},
}

// menuLabel is a simple label+index pair for menu items.
type menuLabel struct {
	label string
}

var menuLabels = []menuLabel{
	{"New Game"},
	{"Puzzle Library"},
	{"History"},
	{"Themes"},
	{"Quit"},
}

// themeItem represents a selectable theme.
type themeItem struct {
	key   string
	label string
}

var themeItems = []themeItem{
	{"modern-charm", "Modern Charm"},
	{"zen-monolith", "Zen Monolith"},
	{"retro-phosphor", "Retro Phosphor"},
	{"matrix", "Matrix"},
}

// Model is the main menu screen.
type Model struct {
	cursor       int
	width        int
	height       int
	showDiff     bool
	diffCursor   int
	showTheme    bool
	themeCursor  int
	activeTheme  string
	theme        *theme.Theme
	generating   bool
	hasSavedGame bool
}

// New creates a new menu model.
func New(th *theme.Theme, hasSavedGame bool) *Model {
	themeCursor := 0
	for i, item := range themeItems {
		if item.key == th.Name {
			themeCursor = i
			break
		}
	}
	return &Model{theme: th, activeTheme: th.Name, themeCursor: themeCursor, hasSavedGame: hasSavedGame}
}

// SetHasSavedGame updates whether a saved game is available to resume.
func (m *Model) SetHasSavedGame(has bool) {
	m.hasSavedGame = has
	if m.cursor > m.maxCursor() {
		m.cursor = m.maxCursor()
	}
}

func (m *Model) effectiveItems() []menuLabel {
	if m.hasSavedGame {
		return append([]menuLabel{{"Resume Game"}}, menuLabels...)
	}
	return menuLabels
}

func (m *Model) maxCursor() int {
	return len(m.effectiveItems()) - 1
}

// SetTheme updates the theme on the menu model.
func (m *Model) SetTheme(th *theme.Theme) {
	m.theme = th
	m.activeTheme = th.Name
	for i, item := range themeItems {
		if item.key == th.Name {
			m.themeCursor = i
			break
		}
	}
}

func (m *Model) Init() tea.Cmd {
	return nil
}

func (m *Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height

	case tea.KeyMsg:
		if m.generating {
			return m, nil
		}
		if m.showDiff {
			return m, m.handleDiffKey(msg)
		}
		if m.showTheme {
			return m, m.handleThemeKey(msg)
		}
		return m, m.handleMenuKey(msg)

	case generateMsg:
		return m, m.startGenerate(msg.diff)
	}

	return m, nil
}

func (m *Model) handleMenuKey(msg tea.KeyMsg) tea.Cmd {
	switch msg.String() {
	case "up", "w":
		if m.cursor > 0 {
			m.cursor--
		}
	case "down", "s":
		if m.cursor < m.maxCursor() {
			m.cursor++
		}
	case "enter", " ":
		return m.activateItem(m.cursor)
	case "q", "esc", "ctrl+c":
		return tea.Quit
	}
	return nil
}

func (m *Model) activateItem(idx int) tea.Cmd {
	if m.hasSavedGame {
		if idx == 0 {
			return func() tea.Msg { return msgs.ResumeGameMsg{} }
		}
		idx-- // shift to base indices
	}
	switch idx {
	case 0: // New Game
		m.showDiff = true
		return nil
	case 1: // Puzzle Library
		return func() tea.Msg { return msgs.NavigateMsg{To: msgs.ScreenLibrary} }
	case 2: // History
		return func() tea.Msg { return msgs.NavigateMsg{To: msgs.ScreenHistory} }
	case 3: // Themes
		m.showTheme = true
		return nil
	case 4: // Quit
		return tea.Quit
	}
	return nil
}

type generateMsg struct {
	diff generator.Difficulty
}

func (m *Model) handleDiffKey(msg tea.KeyMsg) tea.Cmd {
	switch msg.String() {
	case "up", "w":
		if m.diffCursor > 0 {
			m.diffCursor--
		}
	case "down", "s":
		if m.diffCursor < len(diffItems)-1 {
			m.diffCursor++
		}
	case "enter", " ":
		diff := diffItems[m.diffCursor].diff
		m.generating = true
		m.showDiff = false
		return func() tea.Msg { return generateMsg{diff: diff} }
	case "esc", "q":
		m.showDiff = false
	}
	return nil
}

func (m *Model) handleThemeKey(msg tea.KeyMsg) tea.Cmd {
	switch msg.String() {
	case "up", "w":
		if m.themeCursor > 0 {
			m.themeCursor--
		}
	case "down", "s":
		if m.themeCursor < len(themeItems)-1 {
			m.themeCursor++
		}
	case "enter", " ":
		selected := themeItems[m.themeCursor].key
		m.showTheme = false
		return func() tea.Msg { return msgs.ChangeThemeMsg{ThemeName: selected} }
	case "esc", "q":
		m.showTheme = false
	}
	return nil
}

func (m *Model) startGenerate(diff generator.Difficulty) tea.Cmd {
	return func() tea.Msg {
		puzzle, solution := generator.Generate(diff)
		m.generating = false
		return msgs.StartGameMsg{
			Difficulty: diff,
			Puzzle:     puzzle,
			Solution:   solution,
		}
	}
}

func (m *Model) View() string {
	if m.width < 80 || m.height < 24 {
		return "Terminal too small. Please resize to at least 80x24."
	}

	th := m.theme

	logo := th.Menu.Title.Render(sudokuLogo)
	subtitle := th.Menu.Subtitle.Render(th.Strings.MenuSubtitle)

	var menuLines []string
	for i, item := range m.effectiveItems() {
		if i == m.cursor {
			menuLines = append(menuLines, th.Menu.ItemActive.Render("▶  "+item.label))
		} else {
			menuLines = append(menuLines, th.Menu.Item.Render("   "+item.label))
		}
	}
	menuStr := strings.Join(menuLines, "\n")

	if m.generating {
		menuStr = th.Menu.Subtitle.Render("  Generating puzzle...")
	}

	body := lipgloss.JoinVertical(lipgloss.Center, logo, "", subtitle, "", "", menuStr)
	centeredBody := lipgloss.Place(m.width, m.height-2, lipgloss.Center, lipgloss.Center, body)

	hints := th.Footer.KeyHint.Render("k/j") + th.Footer.KeyLabel.Render(" Navigate") +
		"   " + th.Footer.KeyHint.Render("Enter") + th.Footer.KeyLabel.Render(" Select") +
		"   " + th.Footer.KeyHint.Render("Esc/q") + th.Footer.KeyLabel.Render(" Quit")
	footer := th.Footer.Bar.Width(m.width).Render("  " + hints)

	result := centeredBody + "\n" + footer

	if m.showDiff {
		modal := m.renderDiffModal()
		return lipgloss.Place(m.width, m.height, lipgloss.Center, lipgloss.Center, modal)
	}

	if m.showTheme {
		modal := m.renderThemeModal()
		return lipgloss.Place(m.width, m.height, lipgloss.Center, lipgloss.Center, modal)
	}

	return result
}

func (m *Model) renderDiffModal() string {
	th := m.theme

	title := th.Diff.Title.Render("[ SELECT DIFFICULTY ]")
	tagline := th.Diff.Tagline.Render(th.Strings.DiffTagline)
	sep := strings.Repeat("─", 35)

	var lines []string
	lines = append(lines, title)
	lines = append(lines, tagline)
	lines = append(lines, sep)
	lines = append(lines, "")

	for i, d := range diffItems {
		var label string
		if i == m.diffCursor {
			label = th.Diff.Active.Render("▶ " + d.label)
		} else {
			label = th.Diff.Option.Render("  " + d.label)
		}
		clues := th.Diff.ClueCount.Render("  " + d.clues)
		lines = append(lines, label)
		lines = append(lines, clues)
		lines = append(lines, "")
	}

	lines = append(lines, sep)
	desc := th.Diff.Desc.Width(35).Render(th.Diff.DescIcon.Render("i") + " " + diffItems[m.diffCursor].desc)
	lines = append(lines, desc)
	lines = append(lines, "")
	hints := th.Footer.KeyHint.Render("w") + " UP  " + th.Footer.KeyHint.Render("s") + " DOWN  " +
		th.Footer.KeyHint.Render("Esc/q") + " BACK  " + th.Footer.KeyHint.Render("Enter") + " SELECT"
	lines = append(lines, hints)

	content := strings.Join(lines, "\n")
	return th.Diff.ModalBorder.Padding(1, 2).Render(content)
}

func (m *Model) renderThemeModal() string {
	th := m.theme
	title := th.Diff.Title.Render("[ SELECT THEME ]")
	sep := strings.Repeat("─", 30)

	var lines []string
	lines = append(lines, title)
	lines = append(lines, sep)
	lines = append(lines, "")

	for i, t := range themeItems {
		label := t.label
		if t.key == m.activeTheme {
			label += " ✓"
		}
		var rendered string
		if i == m.themeCursor {
			rendered = th.Diff.Active.Render("▶ " + label)
		} else {
			rendered = th.Diff.Option.Render("  " + label)
		}
		lines = append(lines, rendered)
		lines = append(lines, "")
	}

	lines = append(lines, sep)
	hints := th.Footer.KeyHint.Render("w") + " UP  " + th.Footer.KeyHint.Render("s") + " DOWN  " +
		th.Footer.KeyHint.Render("Esc/q") + " BACK  " + th.Footer.KeyHint.Render("Enter") + " SELECT"
	lines = append(lines, hints)

	content := strings.Join(lines, "\n")
	return th.Diff.ModalBorder.Padding(1, 2).Render(content)
}
